const CACHE_NAME="speedtest-v3",urlsToCache=["/","/index.html","/style.css","/script.js","/script.min.js","https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js","https://unpkg.com/web-vitals"];self.addEventListener("install",t=>{t.waitUntil(caches.open(CACHE_NAME).then(t=>t.addAll(urlsToCache)))}),self.addEventListener("fetch",t=>{t.respondWith(caches.match(t.request).then(e=>e||fetch(t.request)))});